import random
import networkx as nx
from itertools import combinations

def has_short_cycle(G, max_len=6):
    """Check if G has any cycle of length <= max_len"""
    for v in G.nodes():
        # BFS from v, check if we find a cycle of length <= max_len
        dist = {v: 0}
        queue = [v]
        parent = {v: -1}
        while queue:
            u = queue.pop(0)
            if dist[u] >= max_len // 2 + 1:
                continue
            for w in G.neighbors(u):
                if w not in dist:
                    dist[w] = dist[u] + 1
                    parent[w] = u
                    queue.append(w)
                elif parent[u] != w:
                    # Found a cycle
                    cycle_len = dist[u] + dist[w] + 1
                    if cycle_len <= max_len:
                        return True, cycle_len
    return False, None

def girth(G):
    """Compute girth of G"""
    if G.number_of_edges() == 0:
        return float('inf')
    min_cycle = float('inf')
    for v in G.nodes():
        dist = {v: 0}
        queue = [v]
        while queue:
            u = queue.pop(0)
            if dist[u] >= min_cycle // 2:
                break
            for w in G.neighbors(u):
                if w not in dist:
                    dist[w] = dist[u] + 1
                    queue.append(w)
                elif dist[u] + dist[w] + 1 < min_cycle:
                    min_cycle = dist[u] + dist[w] + 1
    return min_cycle

def is_k_colorable(G, k):
    """Check if G is k-colorable using greedy + backtracking"""
    colors = {}
    nodes = list(G.nodes())

    def backtrack(idx):
        if idx == len(nodes):
            return True
        v = nodes[idx]
        used = {colors[u] for u in G.neighbors(v) if u in colors}
        for c in range(k):
            if c not in used:
                colors[v] = c
                if backtrack(idx + 1):
                    return True
                del colors[v]
        return False

    return backtrack(0)

