# No networkx - implement from scratch
import random
from itertools import combinations
from collections import deque

def girth(adj, n):
    """Compute girth using BFS from each vertex"""
    min_cycle = float('inf')
    for start in range(n):
        dist = [-1] * n
        dist[start] = 0
        queue = deque([start])
        while queue:
            u = queue.popleft()
            if dist[u] + 1 >= min_cycle:
                continue
            for w in adj[u]:
                if dist[w] == -1:
                    dist[w] = dist[u] + 1
                    queue.append(w)
                elif dist[w] >= dist[u]:
                    # Found cycle of length dist[u] + dist[w] + 1
                    cycle_len = dist[u] + dist[w] + 1
                    if cycle_len < min_cycle:
                        min_cycle = cycle_len
    return min_cycle

def is_k_colorable(adj, n, k):
    """Check k-colorability with backtracking"""
    colors = [-1] * n
    # Order by degree (descending)
    degrees = [len(adj[v]) for v in range(n)]
    order = sorted(range(n), key=lambda v: -degrees[v])

    def backtrack(idx):
        if idx == n:
            return True
        v = order[idx]
        used = {colors[u] for u in adj[v] if colors[u] != -1}
        for c in range(k):
            if c not in used:
                colors[v] = c
                if backtrack(idx + 1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

def add_edge(adj, u, v):
    adj[u].add(v)
    adj[v].add(u)

def remove_edge(adj, u, v):
    adj[u].discard(v)
    adj[v].discard(u)

def has_edge(adj, u, v):
    return v in adj[u]

def num_edges(adj, n):
    return sum(len(adj[v]) for v in range(n)) // 2

def check_girth_after_add(adj, n, u, v, min_girth):
    """Check if adding edge (u,v) would create a cycle shorter than min_girth"""
    # Find shortest path from u to v in current graph (without the new edge)
    dist = [-1] * n
    dist[u] = 0
    queue = deque([u])
    while queue:
        x = queue.popleft()
        if dist[x] + 1 >= min_girth - 1:
            break
        for w in adj[x]:
            if w == v and dist[x] + 1 < min_girth - 1:
                return False  # Would create short cycle
            if dist[w] == -1:
                dist[w] = dist[x] + 1
                queue.append(w)
    if dist[v] != -1 and dist[v] < min_girth - 1:
        return False
    return True

N = 15
MIN_GIRTH = 7
MIN_EDGES = 23
K = 4

best_edges = 0
best_adj = None

random.seed(42)

for trial in range(50000):
    adj = [set() for _ in range(N)]

    edges = list(combinations(range(N), 2))
    random.shuffle(edges)

    for u, v in edges:
        if check_girth_after_add(adj, N, u, v, MIN_GIRTH):
            add_edge(adj, u, v)

    ne = num_edges(adj, N)
    if ne > best_edges:
        best_edges = ne
        best_adj = [s.copy() for s in adj]
        if ne >= MIN_EDGES:
            g = girth(adj, N)
            colorable = is_k_colorable(adj, N, K)
            print(f"Trial {trial}: {ne} edges, girth={g}, {K}-colorable={colorable}")
            if colorable and g >= MIN_GIRTH:
                print("SUCCESS!")
                break

print(f"\nBest: {best_edges} edges")
if best_adj:
    g = girth(best_adj, N)
    colorable = is_k_colorable(best_adj, N, K)
    print(f"Girth: {g}, 4-colorable: {colorable}")
    print("Edges:", [(u,v) for u in range(N) for v in best_adj[u] if u < v])
